#!/usr/bin/env bash
#
# Refresh the published OpenAPI documents from a Gerrit checkout's build outputs.
#
# gerrit-openapi is a distribution point, not a source of truth: every document here is
# a byte-for-byte copy of a Gerrit build output. Run this to re-sync after a spec change,
# then review the diff, commit, and -- at a release -- tag (e.g. v3.15.0) so consumers
# can pin an immutable spec.
#
# The core spec is generated by the gerrit_rules_openapi ruleset wired into Gerrit's
# //tools/openapi package. The gerrit checkout pins that ruleset by commit in its
# MODULE.bazel archive_override; the sibling ../gerrit_rules_openapi must contain that
# commit. The statistics tool is read from the pinned commit object (not the working
# tree), so the numbers match the pinned toolchain regardless of local edits.
#
# Usage: ./update.sh [path-to-gerrit-checkout]     (default: ../gerrit6)
# OPENAPI_RULESET_PATH=/path/to/clean/ruleset selects a local committed ruleset
# before its archive pin is published. It does not update Gerrit's module pin.
set -euo pipefail
cd "$(dirname "$0")"

SRC=${1:-../gerrit6}
[ -d "$SRC" ] || { echo "error: gerrit checkout not found: $SRC" >&2; exit 1; }
SRC=$(cd "$SRC" && pwd)

if command -v bazelisk >/dev/null; then
  BAZEL=bazelisk
else
  BAZEL=bazel
fi
BAZEL_FLAGS=(--noannounce_rc)
RULESET="$SRC/../gerrit_rules_openapi"
if [ -n "${OPENAPI_RULESET_PATH:-}" ]; then
  RULESET=$(cd "$OPENAPI_RULESET_PATH" && pwd)
  [ -z "$(git -C "$RULESET" status --porcelain)" ] || {
    echo "update.sh: local ruleset must be clean so generation matches its commit" >&2
    exit 1
  }
  PIN=$(git -C "$RULESET" rev-parse HEAD)
  BAZEL_FLAGS+=("--override_module=gerrit_rules_openapi=$RULESET" --lockfile_mode=off)
  echo "Using local ruleset $PIN; Gerrit's committed archive pin is unchanged."
else
  PIN=$(sed -nE 's#.*/archive/([0-9a-f]{40})\.tar\.gz.*#\1#p' "$SRC/MODULE.bazel" | head -1)
  [ -n "$PIN" ] || {
    echo "update.sh: could not parse the ruleset archive pin from $SRC/MODULE.bazel" >&2
    exit 1
  }
fi
git -C "$RULESET" cat-file -e "${PIN}^{commit}" 2>/dev/null || {
  echo "update.sh: $RULESET does not contain the selected ruleset commit $PIN; fetch it." >&2
  exit 1
}

# core per-area slices (target //tools/openapi:openapi_<name>_json)
DOMAINS=(access accounts changes config flow groups plugins projects)
# plugins with their own OpenAPI document: "<package-dir> <target-name>"
# Migrated onto the ruleset's openapi_plugin_spec (root-BUILD targets); their
# context_overrides compose underneath core's //tools/openapi generated overrides.
PLUGINS=(
  "checks checks_openapi_json"
  "code-owners code_owners_openapi_json"
)

echo "1/6 build the OpenAPI documents in $SRC"
# openapi_json also drives the miner's worklist report (openapi-overrides-report.json),
# which the statistics step reads; name it so it is always present in bazel-bin.
TARGETS="//tools/openapi:openapi_json //tools/openapi:openapi-overrides-report.json"
for d in "${DOMAINS[@]}"; do TARGETS="$TARGETS //tools/openapi:openapi_${d}_json"; done
for entry in "${PLUGINS[@]}"; do
  set -- $entry
  TARGETS="$TARGETS //plugins/$1:$2"
done
# Keep success quiet (just bazel's summary line) but surface the full log on failure --
# piping straight to `tail -1` would swallow the actual error and mask bazel's exit code.
BUILD_LOG=$(mktemp)
if ( cd "$SRC" && "$BAZEL" build "${BAZEL_FLAGS[@]}" $TARGETS ) >"$BUILD_LOG" 2>&1; then
  tail -1 "$BUILD_LOG"
else
  echo "   build FAILED in $SRC -- bazel output:" >&2
  cat "$BUILD_LOG" >&2
  rm -f "$BUILD_LOG"
  exit 1
fi

echo "2/6 run the publishing gates before copying outputs"
# The slice-parity gate is `manual` (like the rest of the pipeline), so this driver must
# invoke it explicitly: a recurrence of the slice-divergence defect builds cleanly and
# even passes the path-count sanity check below, yet fails this gate. Run the semantic and
# endpoint-golden gates in the same pass so a drifted document cannot be published.
GATE_TARGETS="//tools/openapi:openapi_domain_slices_test"
GATE_TARGETS="$GATE_TARGETS //tools/openapi:all_domain_spec_test"
GATE_TARGETS="$GATE_TARGETS //tools/openapi:all_domain_golden_test"
for entry in "${PLUGINS[@]}"; do
  set -- $entry
  GATE_TARGETS="$GATE_TARGETS //plugins/$1:${2}_spec_test //plugins/$1:${2}_golden_test"
done
if ( cd "$SRC" && "$BAZEL" test "${BAZEL_FLAGS[@]}" $GATE_TARGETS ) >>"$BUILD_LOG" 2>&1; then
  tail -1 "$BUILD_LOG"
  rm -f "$BUILD_LOG"
else
  echo "   publishing gate FAILED in $SRC -- bazel output:" >&2
  cat "$BUILD_LOG" >&2
  rm -f "$BUILD_LOG"
  exit 1
fi

BIN="$SRC/bazel-bin"
echo "3/6 copy build outputs into the published tree"
cp "$BIN/tools/openapi/all-domain-openapi.generated.json" core/openapi.json
for d in "${DOMAINS[@]}"; do
  cp "$BIN/tools/openapi/${d}-openapi.generated.json" "core/domains/${d}.json"
done
for entry in "${PLUGINS[@]}"; do
  set -- $entry
  mkdir -p "plugins/$1"
  cp "$BIN/plugins/$1/$2.generated.json" "plugins/$1/openapi.json"
done
# bazel outputs are read-only; the published copies are normal files.
chmod -R u+w core plugins

echo "4/6 sanity: the domain slices must partition the monolith"
python3 - <<'PY'
import glob, json, sys
mono = len(json.load(open("core/openapi.json")).get("paths", {}))
areas = sum(len(json.load(open(f)).get("paths", {})) for f in glob.glob("core/domains/*.json"))
ver = json.load(open("core/openapi.json")).get("info", {}).get("version")
ok = mono == areas
print(f"   core paths={mono}  sum(core/domains)={areas}  version={ver}  "
      f"[{'partition OK' if ok else 'PARTITION MISMATCH'}]")
sys.exit(0 if ok else 1)
PY

echo "5/6 refresh statistics (rendered from the ruleset's stats tool -- one source, no recompute)"
# The stats tool lives in the gerrit_rules_openapi ruleset (lifted out of core's
# //tools/openapi/py). It emits JSON and gen_stats.py only formats it into
# STATISTICS.md and accumulates the per-release history. Read the tool from the PINNED
# ruleset commit object (git show), not the sibling working tree: a HEAD check alone
# would accept a locally edited tool at the matching HEAD and feed the published numbers.
# Reading the blob at the pin is byte-exact to the pinned toolchain regardless of local
# edits. Fail -- do not silently skip -- if the pin cannot be parsed or is not present.
STATS_TOOL=$(mktemp)
git -C "$RULESET" show "${PIN}:extractor/py/stats_report.py" > "$STATS_TOOL" 2>/dev/null || {
  echo "update.sh: pinned ruleset commit $PIN has no extractor/py/stats_report.py" >&2
  exit 1
}
SNAP=$(mktemp)
python3 "$STATS_TOOL" --json \
  "$BIN/tools/openapi/all-domain-openapi.generated.json" \
  "$BIN/tools/openapi/openapi-overrides-report.json" > "$SNAP"
python3 tools/gen_stats.py --stats "$SNAP"
rm -f "$STATS_TOOL"
rm -f "$SNAP"

echo "6/6 build the distributable bundle (joined spec + all domains + manifest)"
# One versioned zip for build-time consumers (e.g. gerrit-openapi-viewer) to pin
# via http_file + sha256 -- one artifact, one hash, atomic across a generation.
VERSION=$(python3 -c 'import json;print(json.load(open("core/openapi.json"))["info"]["version"])')
mkdir -p dist
BUNDLE="dist/openapi-json-bundle-${VERSION}.zip"
STAGE=$(mktemp -d)
cp core/openapi.json "$STAGE/openapi.json"
mkdir -p "$STAGE/domains" && cp core/domains/*.json "$STAGE/domains/"
python3 - "$STAGE" "$VERSION" <<'PY'
import glob, hashlib, json, os, sys
stage, version = sys.argv[1], sys.argv[2]
sha = lambda f: hashlib.sha256(open(f, "rb").read()).hexdigest()
files = {os.path.relpath(f, stage): sha(f)
         for f in [os.path.join(stage, "openapi.json"), *sorted(glob.glob(stage + "/domains/*.json"))]}
json.dump({"version": version, "files": files},
          open(os.path.join(stage, "manifest.json"), "w"), indent=2, sort_keys=True)
PY
rm -f "$BUNDLE"
# Reproducible archive: pin every entry's mtime to the zip epoch, normalize permissions
# (zip records the mode, which otherwise follows the caller's umask), and add entries in a
# stable sorted order, so identical content always yields the identical zip (and sha256).
# Without this the archive embedded wall-clock mtimes and umask-dependent modes, so each
# regeneration produced a new hash and the consumer's http_file sha256 pin was brittle.
BUNDLE_ABS="$PWD/$BUNDLE"
find "$STAGE" -type f -exec touch -t 198001010000.00 {} +
find "$STAGE" -type f -exec chmod 0644 {} +
( cd "$STAGE" && zip -qX "$BUNDLE_ABS" $(find openapi.json domains manifest.json -type f | LC_ALL=C sort) )
rm -rf "$STAGE"
printf '   wrote %s (sha256 %s)\n' "$BUNDLE" "$(shasum -a 256 "$BUNDLE" | cut -d' ' -f1)"
echo "   publish: git tag v${VERSION} && gh release create v${VERSION} \"$BUNDLE\" --title \"$VERSION\""

echo
echo "done. Review the diff and commit; at a release, tag to match info.version:"
git status --short core plugins STATISTICS.md stats || true
